## Code Example
```typescript
type LogEvent = { timestamp: number; level: string; message: string; meta?: any };
export interface ISink { init(): void; write(event: LogEvent): void; }
export interface Sampler { shouldSample(event: LogEvent, context?: any): boolean; }
export class SinkRegistry { private map = new Map<string, ISink>(); register(n: string, s: ISink){ this.map.set(n, s); } get(n: string){ return this.map.get(n)!; } }
export class SamplerRegistry { private map = new Map<string, Sampler>(); register(n: string, s: Sampler){ this.map.set(n, s); } get(n: string){ return this.map.get(n)!; } }
export class CoreLogger {
  constructor(private sinks: SinkRegistry, private samplers: SamplerRegistry, private defaultSink: string, private defaultSampler: string) {}
  log(event: LogEvent, sinkName?: string, samplerName?: string){
    const s = sinkName ?? this.defaultSink; const sp = samplerName ?? this.defaultSampler;
    if (this.samplers.get(sp).shouldSample(event)) {
      this.sinks.get(s).write(event);
    }
  }
}
```

